const input = $('Execute Workflow Trigger').first().json;
const andrewContactId = 'vKJiakihiqLs3DXR6kfe';

const firstName = input.firstName || '';
const lastName = input.lastName || '';
const phone = input.phone || 'N/A';
const address = input.address || 'N/A';
const source = input.source || 'Unknown';
const roofType = input.selected_roof_type || 'N/A';
const roofSize = (input.roofSize !== undefined && input.roofSize !== null && input.roofSize !== '')
  ? `${input.roofSize} squares`
  : 'N/A';
const reason = input.project_reason || 'N/A';
const timeline = input.homeowner_timeline || 'N/A';
const insurance = input.insurance_claim_status || 'N/A';

const message = `New ${source} lead: ${firstName} ${lastName}
Phone: ${phone}
Address: ${address}
Roof: ${roofType}
Size: ${roofSize}
Reason: ${reason}
Timeline: ${timeline}
Insurance: ${insurance}`;

return [{ json: { andrewContactId, message } }];
